"""Curated cross-period archaeology expansion.

This is deliberately data, not a second archaeology system.  The records are
merged into :mod:`archaeology_content` and use its existing site, item,
Scripture-link, media, map, and rights-aware import paths.
"""

from __future__ import annotations

from typing import Any


def _site(
    id: str, name: str, site_type: str, period: str, latitude: float,
    longitude: float, modern_location: str, region: str, description: str,
    source_name: str, source_url: str, *, periods: list[str], notes: str = "",
) -> dict[str, Any]:
    return {
        "id": id, "name": name, "site_type": site_type, "period": period,
        "periods": periods, "latitude": latitude, "longitude": longitude,
        "modern_location": modern_location, "ancient_region": region,
        "description": description, "confidence": "strong", "confidence_rank": 5,
        "source_name": source_name, "source_url": source_url,
        "license": "Institutional source", "notes": notes or "Site-center coordinate for map display.",
    }


def _item(
    id: str, site_id: str, name: str, item_type: str, period: str,
    relationship: str, why: str, caution: str, description: str, discovery: str,
    physical: str, summary: str, relevance: str, date_display: str,
    dating: str, scholarly: str, location: str, source_name: str, source_url: str,
    *, periods: list[str], dispute: str = "not_disputed", confidence: str = "strong",
) -> dict[str, Any]:
    return {
        "id": id, "site_id": site_id, "name": name, "item_type": item_type,
        "period": period, "periods": periods, "relationship": relationship,
        "why_it_matters": why, "bhf_caution": caution, "confidence": confidence,
        "confidence_rank": 5 if confidence == "strong" else 4,
        "source_name": source_name, "source_url": source_url,
        "license": "Institutional source", "notes": "Reviewed institutional or academic source; media is added only after separate rights review.",
        "evidence_details": {
            "description": description, "discovery_context": discovery,
            "date_display": date_display, "dating_basis": dating,
            "physical_description": physical, "evidence_summary": summary,
            "biblical_relevance": relevance, "scholarly_context": scholarly,
            "interpretive_caution": caution, "current_location": location,
            "dispute_status": dispute,
        },
    }


